import type { GradeOrAll, ModuleId } from '../types';

export interface EntryMeta {
  id: string;
  moduleId: ModuleId;
  title: string;
  subtitle: string;
  grade: GradeOrAll;
  /** 该条目的题目数（不含古诗词现场生成的默写题） */
  questions: number;
  /** 条目标签（「学一补多」的同类作品分组会用到） */
  tags: string[];
  /** 作者（仅古诗词/文言文非空；用于跨模块的「同作者」分组） */
  authors: string[];
  /** 文学常识的命中表：哪些条目命中了它、命中多强（仅文学常识条目非空） */
  matchFrom: { id: string; score: number }[];
  /** 意象名（仅古诗词非空；用于「同类作品」的同意象比较） */
  imagery: string[];
  /** 词条名（仅词语模块非空；用于「本篇涉及的字词」分组） */
  term: string;
  /** 该条目题目上的知识点标签（用于跨模块的「同一考点」分组） */
  qTags: string[];
}

/**
 * 解析紧凑写的命中表（`"id:score"` 空格分隔，见 `scripts/gen-summary.ts`）。
 * 只有文学常识条目的命中表非空，其余传空串直接返回空数组。
 */
export function parseMatchFrom(raw: string): { id: string; score: number }[] {
  if (!raw) return [];
  return raw.split(' ').map((s) => {
    const i = s.lastIndexOf(':');
    return { id: s.slice(0, i), score: Number(s.slice(i + 1)) };
  });
}

export interface ModuleTotals {
  id: ModuleId;
  entries: number;
  questions: number;
  mindMaps: number;
  extensions: number;
}

