/** 每日一句用的名句池（首页按日期轮换） */
export const DAILY_LINES: { text: string; from: string; entryId: string }[] = [
  { text: "日月之行，若出其中；星汉灿烂，若出其里。", from: "东汉·曹操《观沧海》", entryId: "p7a-guan-cang-hai" },
  { text: "我寄愁心与明月，随君直到夜郎西。", from: "唐·李白《闻王昌龄左迁龙标遥有此寄》", entryId: "p7a-wen-wang-changling-zuoqian-longbiao" },
  { text: "海日生残夜，江春入旧年。", from: "唐·王湾《次北固山下》", entryId: "p7a-ci-beigushan-xia" },
  { text: "潮平两岸阔，风正一帆悬。", from: "唐·王湾《次北固山下》", entryId: "p7a-ci-beigushan-xia" },
  { text: "夕阳西下，断肠人在天涯。", from: "元·马致远《天净沙·秋思》", entryId: "p7a-tian-jing-sha-qiu-si" },
  { text: "峨眉山月半轮秋，影入平羌江水流。", from: "唐·李白《峨眉山月歌》", entryId: "p7a-emei-shan-yue-ge" },
  { text: "正是江南好风景，落花时节又逢君。", from: "唐·杜甫《江南逢李龟年》", entryId: "p7a-jiang-nan-feng-li-gui-nian" },
  { text: "遥怜故园菊，应傍战场开。", from: "唐·岑参《行军九日思长安故园》", entryId: "p7a-xing-jun-jiu-ri-si-chang-an-gu-yuan" },
  { text: "不知何处吹芦管，一夜征人尽望乡。", from: "唐·李益《夜上受降城闻笛》", entryId: "p7a-ye-shang-shou-xiang-cheng-wen-di" },
  { text: "晴空一鹤排云上，便引诗情到碧霄。", from: "唐·刘禹锡《秋词（其一）》", entryId: "p7a-qiu-ci-qi-yi" },
  { text: "何当共剪西窗烛，却话巴山夜雨时。", from: "唐·李商隐《夜雨寄北》", entryId: "p7a-ye-yu-ji-bei" },
  { text: "夜阑卧听风吹雨，铁马冰河入梦来。", from: "宋·陆游《十一月四日风雨大作（其二）》", entryId: "p7a-shi-yi-yue-si-ri-feng-yu-da-zuo-qi-er" },
  { text: "河流大野犹嫌束，山入潼关不解平。", from: "清·谭嗣同《潼关》", entryId: "p7a-tong-guan" },
  { text: "学而不思则罔，思而不学则殆。", from: "先秦·孔子及其弟子《《论语》十二章（节选）》", entryId: "p7a-lun-yu-shi-er-zhang" },
  { text: "三人行，必有我师焉。", from: "先秦·孔子及其弟子《《论语》十二章（节选）》", entryId: "p7a-lun-yu-shi-er-zhang" },
  { text: "三军可夺帅也，匹夫不可夺志也。", from: "先秦·孔子及其弟子《《论语》十二章（节选）》", entryId: "p7a-lun-yu-shi-er-zhang" },
  { text: "逝者如斯夫，不舍昼夜。", from: "先秦·孔子及其弟子《《论语》十二章（节选）》", entryId: "p7a-lun-yu-shi-er-zhang" },
  { text: "非淡泊无以明志，非宁静无以致远。", from: "三国·诸葛亮《诫子书》", entryId: "p7a-jie-zi-shu" },
  { text: "狼亦黠矣，而顷刻两毙，禽兽之变诈几何哉？止增笑耳。", from: "清·蒲松龄《狼（节选）》", entryId: "p7a-lang" },
  { text: "未若柳絮因风起。", from: "南朝宋·刘义庆《咏雪》", entryId: "p7a-yong-xue" },
  { text: "日中不至，则是无信；对子骂父，则是无礼。", from: "南朝宋·刘义庆《陈太丘与友期行》", entryId: "p7a-chen-tai-qiu-yu-you-qi-xing" },
  { text: "万里赴戎机，关山度若飞。", from: "北朝·佚名《木兰诗》", entryId: "p7b-mu-lan-shi" },
  { text: "将军百战死，壮士十年归。", from: "北朝·佚名《木兰诗》", entryId: "p7b-mu-lan-shi" },
  { text: "双兔傍地走，安能辨我是雄雌？", from: "北朝·佚名《木兰诗》", entryId: "p7b-mu-lan-shi" },
  { text: "念天地之悠悠，独怆然而涕下！", from: "唐·陈子昂《登幽州台歌》", entryId: "p7b-deng-you-zhou-tai-ge" },
  { text: "会当凌绝顶，一览众山小。", from: "唐·杜甫《望岳》", entryId: "p7b-wang-yue" },
  { text: "不畏浮云遮望眼，自缘身在最高层。", from: "宋·王安石《登飞来峰》", entryId: "p7b-deng-fei-lai-feng" },
  { text: "山重水复疑无路，柳暗花明又一村。", from: "宋·陆游《游山西村》", entryId: "p7b-you-shan-xi-cun" },
  { text: "落红不是无情物，化作春泥更护花。", from: "清·龚自珍《己亥杂诗（其五）》", entryId: "p7b-ji-hai-za-shi-qi-wu" },
  { text: "山不在高，有仙则名。", from: "唐·刘禹锡《陋室铭》", entryId: "p7b-lou-shi-ming" },
  { text: "斯是陋室，惟吾德馨。", from: "唐·刘禹锡《陋室铭》", entryId: "p7b-lou-shi-ming" },
  { text: "苔痕上阶绿，草色入帘青。", from: "唐·刘禹锡《陋室铭》", entryId: "p7b-lou-shi-ming" },
  { text: "予独爱莲之出淤泥而不染，濯清涟而不妖。", from: "宋·周敦颐《爱莲说》", entryId: "p7b-ai-lian-shuo" },
  { text: "然则天下之事，但知其一，不知其二者多矣，可据理臆断欤？", from: "清·纪昀《河中石兽（节选）》", entryId: "p7b-he-zhong-shi-shou" },
  { text: "深林人不知，明月来相照。", from: "唐·王维《竹里馆》", entryId: "p7b-zhu-li-guan" },
  { text: "此夜曲中闻折柳，何人不起故园情。", from: "唐·李白《春夜洛城闻笛》", entryId: "p7b-chun-ye-luo-cheng-wen-di" },
  { text: "马上相逢无纸笔，凭君传语报平安。", from: "唐·岑参《逢入京使》", entryId: "p7b-feng-ru-jing-shi" },
  { text: "草树知春不久归，百般红紫斗芳菲。", from: "唐·韩愈《晚春》", entryId: "p7b-wan-chun" },
  { text: "商女不知亡国恨，隔江犹唱后庭花。", from: "唐·杜牧《泊秦淮》", entryId: "p7b-bo-qin-huai" },
  { text: "可怜夜半虚前席，不问苍生问鬼神。", from: "唐·李商隐《贾生》", entryId: "p7b-jia-sheng" },
  { text: "士别三日，即更刮目相待。", from: "宋·司马光《孙权劝学》", entryId: "p7b-sun-quan-quan-xue" },
  { text: "无他，但手熟尔。", from: "宋·欧阳修《卖油翁》", entryId: "p7b-mai-you-weng" },
  { text: "树树皆秋色，山山唯落晖。", from: "唐·王绩《野望》", entryId: "p8a-ye-wang" },
  { text: "日暮乡关何处是？烟波江上使人愁。", from: "唐·崔颢《黄鹤楼》", entryId: "p8a-huang-he-lou" },
  { text: "大漠孤烟直，长河落日圆。", from: "唐·王维《使至塞上》", entryId: "p8a-shi-zhi-sai-shang" },
  { text: "山随平野尽，江入大荒流。", from: "唐·李白《渡荆门送别》", entryId: "p8a-du-jing-men-song-bie" },
  { text: "几处早莺争暖树，谁家新燕啄春泥。", from: "唐·白居易《钱塘湖春行》", entryId: "p8a-qian-tang-hu-chun-xing" },
  { text: "乱花渐欲迷人眼，浅草才能没马蹄。", from: "唐·白居易《钱塘湖春行》", entryId: "p8a-qian-tang-hu-chun-xing" },
  { text: "馨香盈怀袖，路远莫致之。", from: "汉·《古诗十九首》《庭中有奇树》", entryId: "p8a-ting-zhong-you-qi-shu" },
  { text: "老骥伏枥，志在千里。", from: "东汉·曹操《龟虽寿》", entryId: "p8a-gui-sui-shou" },
  { text: "烈士暮年，壮心不已。", from: "东汉·曹操《龟虽寿》", entryId: "p8a-gui-sui-shou" },
  { text: "岂不罹凝寒，松柏有本性。", from: "东汉·刘桢《赠从弟（其二）》", entryId: "p8a-zeng-cong-di-qi-er" },
  { text: "柴门何萧条，狐兔翔我宇。", from: "东汉·曹植《梁甫行》", entryId: "p8a-liang-fu-xing" },
  { text: "自非亭午夜分，不见曦月。", from: "北魏·郦道元《三峡》", entryId: "p8a-san-xia" },
  { text: "清荣峻茂，良多趣味。", from: "北魏·郦道元《三峡》", entryId: "p8a-san-xia" },
  { text: "高峰入云，清流见底。", from: "南朝·陶弘景《答谢中书书》", entryId: "p8a-da-xie-zhong-shu-shu" },
  { text: "夕日欲颓，沉鳞竞跃。", from: "南朝·陶弘景《答谢中书书》", entryId: "p8a-da-xie-zhong-shu-shu" },
  { text: "庭下如积水空明，水中藻、荇交横，盖竹柏影也。", from: "宋·苏轼《记承天寺夜游》", entryId: "p8a-ji-cheng-tian-si-ye-you" },
  { text: "风烟俱净，天山共色。", from: "南朝·吴均《与朱元思书》", entryId: "p8a-yu-zhu-yuan-si-shu" },
  { text: "急湍甚箭，猛浪若奔。", from: "南朝·吴均《与朱元思书》", entryId: "p8a-yu-zhu-yuan-si-shu" },
  { text: "鸢飞戾天者，望峰息心；经纶世务者，窥谷忘反。", from: "南朝·吴均《与朱元思书》", entryId: "p8a-yu-zhu-yuan-si-shu" },
  { text: "富贵不能淫，贫贱不能移，威武不能屈。", from: "先秦·孟子《富贵不能淫》", entryId: "p8a-fu-gui-bu-neng-yin" },
  { text: "得志，与民由之；不得志，独行其道。", from: "先秦·孟子《富贵不能淫》", entryId: "p8a-fu-gui-bu-neng-yin" },
  { text: "故天将降大任于是人也，必先苦其心志，劳其筋骨。", from: "先秦·孟子《生于忧患，死于安乐》", entryId: "p8a-sheng-yu-you-huan" },
  { text: "生于忧患而死于安乐。", from: "先秦·孟子《生于忧患，死于安乐》", entryId: "p8a-sheng-yu-you-huan" },
  { text: "采菊东篱下，悠然见南山。", from: "东晋·陶渊明《饮酒（其五）》", entryId: "p8a-yin-jiu-qi-wu" },
  { text: "烽火连三月，家书抵万金。", from: "唐·杜甫《春望》", entryId: "p8a-chun-wang" },
  { text: "感时花溅泪，恨别鸟惊心。", from: "唐·杜甫《春望》", entryId: "p8a-chun-wang" },
  { text: "黑云压城城欲摧，甲光向日金鳞开。", from: "唐·李贺《雁门太守行》", entryId: "p8a-yan-men-tai-shou-xing" },
  { text: "报君黄金台上意，提携玉龙为君死。", from: "唐·李贺《雁门太守行》", entryId: "p8a-yan-men-tai-shou-xing" },
  { text: "东风不与周郎便，铜雀春深锁二乔。", from: "唐·杜牧《赤壁》", entryId: "p8a-chi-bi" },
  { text: "九万里风鹏正举。风休住，蓬舟吹取三山去！", from: "宋·李清照《渔家傲》", entryId: "p8a-yu-jia-ao" },
  { text: "阡陌交通，鸡犬相闻。", from: "东晋·陶渊明《桃花源记（节选）》", entryId: "p8b-tao-hua-yuan-ji" },
  { text: "黄发垂髫，并怡然自乐。", from: "东晋·陶渊明《桃花源记（节选）》", entryId: "p8b-tao-hua-yuan-ji" },
  { text: "潭中鱼可百许头，皆若空游无所依。", from: "唐·柳宗元《小石潭记》", entryId: "p8b-xiao-shi-tan-ji" },
  { text: "凄神寒骨，悄怆幽邃。", from: "唐·柳宗元《小石潭记》", entryId: "p8b-xiao-shi-tan-ji" },
  { text: "罔不因势象形，各具情态。", from: "明·魏学洢《核舟记（节选）》", entryId: "p8b-he-zhou-ji" },
  { text: "关关雎鸠，在河之洲。窈窕淑女，君子好逑。", from: "先秦·《诗经》《关雎》", entryId: "p8b-guan-ju" },
  { text: "蒹葭苍苍，白露为霜。所谓伊人，在水一方。", from: "先秦·《诗经》《蒹葭》", entryId: "p8b-jian-jia" },
  { text: "水击三千里，抟扶摇而上者九万里。", from: "先秦·庄子《北冥有鱼》", entryId: "p8b-bei-ming-you-yu" },
  { text: "其翼若垂天之云。", from: "先秦·庄子《北冥有鱼》", entryId: "p8b-bei-ming-you-yu" },
  { text: "教学相长也。", from: "先秦·《礼记》《虽有嘉肴》", entryId: "p8b-sui-you-jia-yao" },
  { text: "学然后知不足，教然后知困。", from: "先秦·《礼记》《虽有嘉肴》", entryId: "p8b-sui-you-jia-yao" },
  { text: "大道之行也，天下为公。", from: "先秦·《礼记》《大道之行也》", entryId: "p8b-da-dao-zhi-xing-ye" },
  { text: "老有所终，壮有所用，幼有所长。", from: "先秦·《礼记》《大道之行也》", entryId: "p8b-da-dao-zhi-xing-ye" },
  { text: "世有伯乐，然后有千里马。", from: "唐·韩愈《马说》", entryId: "p8b-ma-shuo" },
  { text: "其真无马邪？其真不知马也！", from: "唐·韩愈《马说》", entryId: "p8b-ma-shuo" },
  { text: "安得广厦千万间，大庇天下寒士俱欢颜！", from: "唐·杜甫《茅屋为秋风所破歌》", entryId: "p8b-mao-wu-wei-qiu-feng-suo-po-ge" },
  { text: "床头屋漏无干处，雨脚如麻未断绝。", from: "唐·杜甫《茅屋为秋风所破歌》", entryId: "p8b-mao-wu-wei-qiu-feng-suo-po-ge" },
  { text: "可怜身上衣正单，心忧炭贱愿天寒。", from: "唐·白居易《卖炭翁》", entryId: "p8b-mai-tan-weng" },
  { text: "曲径通幽处，禅房花木深。", from: "唐·常建《题破山寺后禅院》", entryId: "p8b-ti-po-shan-si-hou-chan-yuan" },
  { text: "山光悦鸟性，潭影空人心。", from: "唐·常建《题破山寺后禅院》", entryId: "p8b-ti-po-shan-si-hou-chan-yuan" },
  { text: "浮云游子意，落日故人情。", from: "唐·李白《送友人》", entryId: "p8b-song-you-ren" },
  { text: "挥手自兹去，萧萧班马鸣。", from: "唐·李白《送友人》", entryId: "p8b-song-you-ren" },
  { text: "拣尽寒枝不肯栖，寂寞沙洲冷。", from: "宋·苏轼《卜算子·黄州定慧院寓居作》", entryId: "p8b-bu-suan-zi-huang-zhou-ding-hui-yuan" },
  { text: "零落成泥碾作尘，只有香如故。", from: "宋·陆游《卜算子·咏梅》", entryId: "p8b-bu-suan-zi-yong-mei" },
  { text: "微君之故，胡为乎中露？", from: "先秦·《诗经》《式微》", entryId: "p8b-shi-wei" },
  { text: "青青子衿，悠悠我心。", from: "先秦·《诗经》《子衿》", entryId: "p8b-zi-jin" },
  { text: "一日不见，如三月兮。", from: "先秦·《诗经》《子衿》", entryId: "p8b-zi-jin" },
  { text: "气蒸云梦泽，波撼岳阳城。", from: "唐·孟浩然《望洞庭湖赠张丞相》", entryId: "p8b-wang-dong-ting-hu" },
  { text: "坐观垂钓者，徒有羡鱼情。", from: "唐·孟浩然《望洞庭湖赠张丞相》", entryId: "p8b-wang-dong-ting-hu" },
  { text: "山舞银蛇，原驰蜡象，欲与天公试比高。", from: "现代·毛泽东《沁园春·雪》", entryId: "p9a-qin-yuan-chun-xue" },
  { text: "俱往矣，数风流人物，还看今朝。", from: "现代·毛泽东《沁园春·雪》", entryId: "p9a-qin-yuan-chun-xue" },
  { text: "为什么我的眼里常含泪水？因为我对这土地爱得深沉……", from: "现代·艾青《我爱这土地》", entryId: "p9a-wo-ai-zhe-tu-di" },
  { text: "而现在，乡愁是一湾浅浅的海峡，我在这头，大陆在那头。", from: "现代·余光中《乡愁》", entryId: "p9a-xiang-chou" },
  { text: "你是爱，是暖，是希望，你是人间的四月天！", from: "现代·林徽因《你是人间的四月天——一句爱的赞颂》", entryId: "p9a-ni-shi-ren-jian-de-si-yue-tian" },
  { text: "先天下之忧而忧，后天下之乐而乐。", from: "宋·范仲淹《岳阳楼记》", entryId: "p9a-yue-yang-lou-ji" },
  { text: "不以物喜，不以己悲。", from: "宋·范仲淹《岳阳楼记》", entryId: "p9a-yue-yang-lou-ji" },
  { text: "醉翁之意不在酒，在乎山水之间也。", from: "宋·欧阳修《醉翁亭记》", entryId: "p9a-zui-weng-ting-ji" },
  { text: "野芳发而幽香，佳木秀而繁阴。", from: "宋·欧阳修《醉翁亭记》", entryId: "p9a-zui-weng-ting-ji" },
  { text: "雾凇沆砀，天与云与山与水，上下一白。", from: "明·张岱《湖心亭看雪》", entryId: "p9a-hu-xin-ting-kan-xue" },
  { text: "长风破浪会有时，直挂云帆济沧海。", from: "唐·李白《行路难（其一）》", entryId: "p9a-xing-lu-nan-qi-yi" },
  { text: "沉舟侧畔千帆过，病树前头万木春。", from: "唐·刘禹锡《酬乐天扬州初逢席上见赠》", entryId: "p9a-chou-le-tian-yang-zhou-chu-feng-xi-shang-jian-zeng" },
  { text: "人有悲欢离合，月有阴晴圆缺，此事古难全。", from: "宋·苏轼《水调歌头（明月几时有）》", entryId: "p9a-shui-diao-ge-tou-ming-yue-ji-shi-you" },
  { text: "但愿人长久，千里共婵娟。", from: "宋·苏轼《水调歌头（明月几时有）》", entryId: "p9a-shui-diao-ge-tou-ming-yue-ji-shi-you" },
  { text: "露从今夜白，月是故乡明。", from: "唐·杜甫《月夜忆舍弟》", entryId: "p9a-yue-ye-yi-she-di" },
  { text: "汉文有道恩犹薄，湘水无情吊岂知？", from: "唐·刘长卿《长沙过贾谊宅》", entryId: "p9a-chang-sha-guo-jia-yi-zhai" },
  { text: "云横秦岭家何在？雪拥蓝关马不前。", from: "唐·韩愈《左迁至蓝关示侄孙湘》", entryId: "p9a-zuo-qian-zhi-lan-guan-shi-zhi-sun-xiang" },
  { text: "鸡声茅店月，人迹板桥霜。", from: "唐·温庭筠《商山早行》", entryId: "p9a-shang-shan-zao-xing" },
  { text: "春蚕到死丝方尽，蜡炬成灰泪始干。", from: "唐·李商隐《无题》", entryId: "p9a-wu-ti-xiang-jian-shi-nan-bie-yi-nan" },
  { text: "溪云初起日沉阁，山雨欲来风满楼。", from: "唐·许浑《咸阳城东楼》", entryId: "p9a-xian-yang-cheng-dong-lou" },
  { text: "有桃花红，李花白，菜花黄。", from: "宋·秦观《行香子（树绕村庄）》", entryId: "p9a-xing-xiang-zi-shu-rao-cun-zhuang" },
  { text: "正莺儿啼，燕儿舞，蝶儿忙。", from: "宋·秦观《行香子（树绕村庄）》", entryId: "p9a-xing-xiang-zi-shu-rao-cun-zhuang" },
  { text: "少年不识愁滋味，爱上层楼。", from: "宋·辛弃疾《丑奴儿·书博山道中壁》", entryId: "p9a-chou-nu-er-shu-bo-shan-dao-zhong-bi" },
  { text: "而今识尽愁滋味，欲说还休。", from: "宋·辛弃疾《丑奴儿·书博山道中壁》", entryId: "p9a-chou-nu-er-shu-bo-shan-dao-zhong-bi" },
  { text: "浊酒一杯家万里，燕然未勒归无计。", from: "宋·范仲淹《渔家傲·秋思》", entryId: "p9b-yu-jia-ao-qiu-si" },
  { text: "人不寐，将军白发征夫泪。", from: "宋·范仲淹《渔家傲·秋思》", entryId: "p9b-yu-jia-ao-qiu-si" },
  { text: "会挽雕弓如满月，西北望，射天狼。", from: "宋·苏轼《江城子·密州出猎》", entryId: "p9b-jiang-cheng-zi-mi-zhou-chu-lie" },
  { text: "了却君王天下事，赢得生前身后名。可怜白发生！", from: "宋·辛弃疾《破阵子·为陈同甫赋壮词以寄之》", entryId: "p9b-po-zhen-zi-wei-chen-tong-fu-fu-zhuang-ci-yi-ji-zhi" },
  { text: "身不得，男儿列，心却比，男儿烈。", from: "清·秋瑾《满江红（小住京华）》", entryId: "p9b-man-jiang-hong-xiao-zhu-jing-hua" },
  { text: "莽红尘何处觅知音？青衫湿！", from: "清·秋瑾《满江红（小住京华）》", entryId: "p9b-man-jiang-hong-xiao-zhu-jing-hua" },
  { text: "竹杖芒鞋轻胜马，谁怕？一蓑烟雨任平生。", from: "宋·苏轼《定风波（莫听穿林打叶声）》", entryId: "p9b-ding-feng-bo-mo-ting-chuan-lin-da-ye-sheng" },
  { text: "回首向来萧瑟处，归去，也无风雨也无晴。", from: "宋·苏轼《定风波（莫听穿林打叶声）》", entryId: "p9b-ding-feng-bo-mo-ting-chuan-lin-da-ye-sheng" },
  { text: "杏花疏影里，吹笛到天明。", from: "宋·陈与义《临江仙·夜登小阁忆洛中旧游》", entryId: "p9b-lin-jiang-xian-ye-deng-xiao-ge-yi-luo-zhong-jiu-you" },
  { text: "斫去桂婆娑，人道是、清光更多。", from: "宋·辛弃疾《太常引·建康中秋夜为吕叔潜赋》", entryId: "p9b-tai-chang-yin-jian-kang-zhong-qiu-ye-wei-lv-shu-qian-fu" },
  { text: "一抹晚烟荒戍垒，半竿斜日旧关城。", from: "清·纳兰性德《浣溪沙（身向云山那畔行）》", entryId: "p9b-huan-xi-sha-shen-xiang-yun-shan-na-pan-xing" },
  { text: "生，亦我所欲也；义，亦我所欲也。二者不可得兼，舍生而取义者也。", from: "先秦·孟子《鱼我所欲也》", entryId: "p9b-yu-wo-suo-yu-ye" },
  { text: "若士必怒，伏尸二人，流血五步，天下缟素，今日是也。", from: "西汉·刘向《唐雎不辱使命》", entryId: "p9b-tang-ju-bu-ru-shi-ming" },
  { text: "余立侍左右，援疑质理，俯身倾耳以请。", from: "明·宋濂《送东阳马生序》", entryId: "p9b-song-dong-yang-ma-sheng-xu" },
  { text: "一鼓作气，再而衰，三而竭。", from: "先秦·左丘明《曹刿论战》", entryId: "p9b-cao-gui-lun-zhan" },
  { text: "群臣进谏，门庭若市。", from: "西汉·刘向《邹忌讽齐王纳谏》", entryId: "p9b-zou-ji-feng-qi-wang-na-jian" },
  { text: "此所谓战胜于朝廷。", from: "西汉·刘向《邹忌讽齐王纳谏》", entryId: "p9b-zou-ji-feng-qi-wang-na-jian" },
  { text: "受任于败军之际，奉命于危难之间。", from: "三国·诸葛亮《出师表》", entryId: "p9b-chu-shi-biao" },
  { text: "亲贤臣，远小人，此先汉所以兴隆也。", from: "三国·诸葛亮《出师表》", entryId: "p9b-chu-shi-biao" },
  { text: "十五从军征，八十始得归。", from: "汉·佚名《十五从军征》", entryId: "p9b-shi-wu-cong-jun-zheng" },
  { text: "出门东向看，泪落沾我衣。", from: "汉·佚名《十五从军征》", entryId: "p9b-shi-wu-cong-jun-zheng" },
  { text: "政入万山围子里，一山放出一山拦。", from: "宋·杨万里《过松源晨炊漆公店（其五）》", entryId: "p7b-guo-song-yuan-chen-chui-qi-gong-dian" },
  { text: "有约不来过夜半，闲敲棋子落灯花。", from: "宋·赵师秀《约客》", entryId: "p7b-yue-ke" },
  { text: "轻舟短棹西湖好，绿水逶迤。", from: "宋·欧阳修《采桑子（轻舟短棹西湖好）》", entryId: "p8a-cai-sang-zi" },
  { text: "微动涟漪，惊起沙禽掠岸飞。", from: "宋·欧阳修《采桑子（轻舟短棹西湖好）》", entryId: "p8a-cai-sang-zi" },
  { text: "万里夕阳垂地大江流。", from: "宋·朱敦儒《相见欢（金陵城上西楼）》", entryId: "p8a-xiang-jian-huan-zhu-dun-ru" },
  { text: "试倩悲风吹泪过扬州。", from: "宋·朱敦儒《相见欢（金陵城上西楼）》", entryId: "p8a-xiang-jian-huan-zhu-dun-ru" },
  { text: "争渡，争渡，惊起一滩鸥鹭。", from: "宋·李清照《如梦令（常记溪亭日暮）》", entryId: "p8a-ru-meng-ling" },
  { text: "山河千古在，城郭一时非。", from: "宋·文天祥《南安军》", entryId: "p9b-nan-an-jun" },
  { text: "饿死真吾志，梦中行采薇。", from: "宋·文天祥《南安军》", entryId: "p9b-nan-an-jun" },
  { text: "无限河山泪，谁言天地宽。", from: "明·夏完淳《别云间》", entryId: "p9b-bie-yun-jian" },
  { text: "毅魄归来日，灵旗空际看。", from: "明·夏完淳《别云间》", entryId: "p9b-bie-yun-jian" },
  { text: "当时奢侈今何处？", from: "元·张养浩《山坡羊·骊山怀古》", entryId: "p9b-shan-po-yang-li-shan" },
  { text: "赢，都变做了土；输，都变做了土。", from: "元·张养浩《山坡羊·骊山怀古》", entryId: "p9b-shan-po-yang-li-shan" },
  { text: "官船来往乱如麻，全仗你抬声价。", from: "明·王磐《朝天子·咏喇叭》", entryId: "p9b-chao-tian-zi-yong-la-ba" },
  { text: "眼见的吹翻了这家，吹伤了那家，只吹的水尽鹅飞罢！", from: "明·王磐《朝天子·咏喇叭》", entryId: "p9b-chao-tian-zi-yong-la-ba" },
  { text: "海内存知己，天涯若比邻。", from: "唐·王勃《送杜少府之任蜀州》", entryId: "p-extra-song-du-shaofu" },
  { text: "忽如一夜春风来，千树万树梨花开。", from: "唐·岑参《白雪歌送武判官归京》", entryId: "p-extra-baixuege" },
  { text: "山回路转不见君，雪上空留马行处。", from: "唐·岑参《白雪歌送武判官归京》", entryId: "p-extra-baixuege" },
  { text: "剪不断，理还乱，是离愁。", from: "五代·李煜《相见欢（无言独上西楼）》", entryId: "p-extra-xiangjianhuan" },
  { text: "别是一般滋味在心头。", from: "五代·李煜《相见欢（无言独上西楼）》", entryId: "p-extra-xiangjianhuan" },
  { text: "无可奈何花落去，似曾相识燕归来。", from: "宋·晏殊《浣溪沙（一曲新词酒一杯）》", entryId: "p-extra-huanshaxi-yanshu" },
  { text: "千古兴亡多少事？悠悠。不尽长江滚滚流。", from: "宋·辛弃疾《南乡子·登京口北固亭有怀》", entryId: "p-extra-nanxiangzi" },
  { text: "天下英雄谁敌手？曹刘。生子当如孙仲谋。", from: "宋·辛弃疾《南乡子·登京口北固亭有怀》", entryId: "p-extra-nanxiangzi" },
  { text: "人生自古谁无死？留取丹心照汗青。", from: "宋·文天祥《过零丁洋》", entryId: "p-extra-guolingdingyang" },
  { text: "山河破碎风飘絮，身世浮沉雨打萍。", from: "宋·文天祥《过零丁洋》", entryId: "p-extra-guolingdingyang" },
  { text: "峰峦如聚，波涛如怒，山河表里潼关路。", from: "元·张养浩《山坡羊·潼关怀古》", entryId: "p-extra-shanpoyang" },
  { text: "兴，百姓苦；亡，百姓苦。", from: "元·张养浩《山坡羊·潼关怀古》", entryId: "p-extra-shanpoyang" },
];

